actual_next_http_readback.query:
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog; SET LOCAL timezone='UTC'; SET LOCAL statement_timeout='10s';
SELECT clock_timestamp() AS observed_at,pg_postmaster_start_time() AS postmaster_started_at,
 (SELECT jsonb_build_object('last_value',last_value::text,'is_called',is_called) FROM jetnity_pgnet_allocator_private.http_request_id_v1) AS own_sequence,
 (SELECT coalesce(jsonb_agg(to_jsonb(x) ORDER BY x.created,x.id),'[]'::jsonb) FROM (
 SELECT id::text,created,status_code,timed_out,(error_msg IS NULL) AS no_error,
 content_type,octet_length(convert_to(content,'UTF8')) AS body_bytes,
 encode(sha256(convert_to(content,'UTF8')),'hex') AS body_sha
 FROM net._http_response WHERE id>=1827 AND created>=pg_postmaster_start_time()
 ORDER BY created,id LIMIT 12)x) AS new_responses,
 public.official_v3_guard_alarm_status_v1() AS bg1;
ROLLBACK;

dispatch_binding.query:
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY; SET LOCAL search_path=pg_catalog; SET LOCAL timezone='UTC'; SET LOCAL statement_timeout='10s';
SELECT clock_timestamp() AS observed_at,
(SELECT jsonb_object_agg(a.attname,format_type(a.atttypid,a.atttypmod)) FROM pg_attribute a WHERE a.attrelid='jetnity_source_dispatch_private.requests_v1'::regclass AND a.attnum>0 AND NOT a.attisdropped) AS dispatch_columns,
(SELECT jsonb_build_object('request_id',request_id::text,'requested_at',to_jsonb(r)->'requested_at','created_at',to_jsonb(r)->'created_at','source_id',to_jsonb(r)->'source_id','state',to_jsonb(r)->'state') FROM jetnity_source_dispatch_private.requests_v1 r WHERE request_id=1827) AS request_metadata,
(SELECT coalesce(jsonb_agg(jsonb_build_object('name',j.jobname,'jobid',j.jobid::text,'active',j.active,'schedule',j.schedule,'db_correct',j.database=current_database(),'role',j.username,'command_sha',encode(sha256(convert_to(j.command,'UTF8')),'hex'),'runid',d.runid::text,'run_command_exact',d.command=j.command,'run_role',d.username,'run_db_correct',d.database=current_database(),'status',d.status,'started_at',d.start_time,'finished_at',d.end_time)),'[]'::jsonb) FROM cron.job j JOIN cron.job_run_details d ON d.jobid=j.jobid WHERE j.jobname LIKE '%source-dispatch%' AND d.start_time>pg_postmaster_start_time()) AS dispatch_cron;
ROLLBACK;

id_prefix_reconciliation.query:
BEGIN TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY;
SET LOCAL search_path=pg_catalog;
SET LOCAL timezone='UTC';
SET LOCAL statement_timeout='10s';
SET LOCAL lock_timeout='2s';
SELECT clock_timestamp() AS observed_at,
 (SELECT jsonb_object_agg(a.attname,format_type(a.atttypid,a.atttypmod)) FROM pg_attribute a
 WHERE a.attrelid='jetnity_source_dispatch_private.observations_v1'::regclass AND a.attnum>0 AND NOT a.attisdropped) AS observation_columns,
 (SELECT jsonb_build_object('request_id',r.request_id::text,
  'observed_at',to_jsonb(r)->'observed_at','collected_at',to_jsonb(r)->'collected_at',
  'created_at',to_jsonb(r)->'created_at','source_id',to_jsonb(r)->'source_id','state',to_jsonb(r)->'state')
 FROM jetnity_source_dispatch_private.observations_v1 r WHERE r.request_id=1826) AS appended_old_request_observation,
 (SELECT jsonb_build_object('request_id',r.request_id::text,'requested_at',to_jsonb(r)->'requested_at','source_id',to_jsonb(r)->'source_id')
 FROM jetnity_source_dispatch_private.requests_v1 r WHERE r.request_id=1826) AS original_request,
 (SELECT jsonb_build_object('rows',count(request_id)::text,
  'ids_sha256',encode(sha256(convert_to(coalesce(string_agg(request_id::text,'|' ORDER BY request_id),''),'UTF8')),'hex'))
 FROM jetnity_source_dispatch_private.observations_v1 WHERE request_id<=1825) AS original_observation_id_prefix;
ROLLBACK;
